    Bug 2002374 - Only try to switch to a pref pane if the tab has loaded the settings already. r=aleca

    Differential Revision: https://phabricator.services.mozilla.com/D274053

diff --git a/mail/components/preferences/preferencesTab.js b/mail/components/preferences/preferencesTab.js
index 108f340926b..ef845f1c496 100644
--- a/mail/components/preferences/preferencesTab.js
+++ b/mail/components/preferences/preferencesTab.js
@@ -41,11 +41,13 @@ var preferencesTabType = {
     if (!this.tab) {
       return -1;
     }
-    this.tab.browser.contentWindow.selectPrefPane(
-      aArgs.paneID,
-      aArgs.scrollPaneTo,
-      aArgs.otherArgs
-    );
+    if (this.tab.pageLoaded) {
+      this.tab.browser.contentWindow.selectPrefPane(
+        aArgs.paneID,
+        aArgs.scrollPaneTo,
+        aArgs.otherArgs
+      );
+    }
     return document.getElementById("tabmail").tabInfo.indexOf(this.tab);
   },
